M = {1: 'Window on the World', 2: 'A Thirst for Knowledge', 3: 'Human Nature', 4: 'Pack Your Bags', 0: 'Writing'}

def mcq(q, o, a): return dict(t='mcq', q=q, o=o, a=a)
def gap(q, a): return dict(t='gap', q=q, a=a)

