dict(id='g12-m3-past-tenses', mod=3, sk=['GR_PAST'], sb='',
 en='Past simple and past continuous (when / while / as)', ar='الماضي البسيط والماضي المستمر',
 table=[('Past simple', 'V2 (played, went) · didn\'t + V · Did … + V?', 'finished action at a known time'),
        ('Past continuous', 'was / were + V-ing', 'action in progress in the past'),
        ('while / as + past continuous', 'While I was cooking, the phone rang.', 'long action interrupted'),
        ('when + past simple', 'I was cooking when the phone rang.', 'short interrupting action'),
        ('while + continuous, continuous', 'While Dad was reading, Mum was cooking.', 'two long actions together'),
        ('Time words', 'yesterday, ago, last …, in 2020 · at 8 pm yesterday, this time last week', '')],
 rule='Long background action → past continuous. Short, complete action → past simple. "When" usually introduces the short action, "while/as" the long one.',
 rule_ar='الحدث الطويل في الخلفية ← الماضي المستمر، والحدث القصير المكتمل ← الماضي البسيط.',
 ex=['We were playing football when it started to rain.', 'While Noor was studying, her brother was watching TV.', 'I lost my phone two days ago.'],
 mistake=('While I walked home, I saw an accident. (weak) ✗', 'While I was walking home, I saw an accident. ✓', 'بعد while نستخدم غالبًا الماضي المستمر.'),
 rem_ins='Choose the correct form.',
 rem=[mcq('I ______ TV when the lights went out.', ['watched', 'was watching', 'am watching', 'watch'], 'was watching'),
      mcq('While she was driving, her phone ______.', ['was ringing', 'rang', 'rings', 'ring'], 'rang'),
      mcq('They ______ to Turkey last summer.', ['were travelling', 'travel', 'travelled', 'have travelled'], 'travelled'),
      mcq('At 9 pm yesterday, we ______ dinner.', ['had', 'were having', 'have', 'are having'], 'were having'),
      mcq('______ you see the match last night?', ['Were', 'Did', 'Do', 'Was'], 'Did'),
      mcq('He broke his arm while he ______.', ['skied', 'was skiing', 'skis', 'ski'], 'was skiing'),
      mcq('When the teacher came in, the students ______ up.', ['were standing', 'stood', 'stand', 'have stood'], 'stood'),
      mcq('While I was reading, my sister ______ the piano.', ['played', 'was playing', 'plays', 'play'], 'was playing')],
 enr_ins='Join the sentences using the word in brackets. Use the correct tenses.',
 enr_box='',
 enr=[gap('I was walking to school. I found a wallet. (when)', 'I was walking to school when I found a wallet.'),
      gap('The guests arrived. We were preparing the food. (while)', 'While we were preparing the food, the guests arrived.'),
      gap('My father was reading. My mother was cooking. (while)', 'While my father was reading, my mother was cooking.'),
      gap('He fell asleep during the film. (as … was watching)', 'He fell asleep as he was watching the film.'),
      gap('The fire alarm rang. Everybody left the building. (when)', 'When the fire alarm rang, everybody left the building.'),
      gap('Write three sentences about an unexpected event using while, when and as soon as.', 'Open answer')]),

dict(id='g12-m3-used-to-would', mod=3, sk=['GR_USED'], sb='',
 en='used to and would for past habits', ar='used to و would للعادات الماضية',
 table=[('used to + V', 'past habits AND past states', 'I used to live in Al Khor.'),
        ("didn't use to + V · Did … use to + V?", 'negative and question (no -d)', ''),
        ('would + V', 'repeated past ACTIONS only (not states)', 'Every Friday we would visit Grandma.'),
        ('be used to + V-ing / noun', 'accustomed now', "I'm used to waking up early."),
        ('get used to + V-ing / noun', 'becoming accustomed', "You'll get used to the heat.")],
 rule='Use used to for habits and states that are no longer true. Use would only for repeated actions, never for states like have, live, like, be.',
 rule_ar='used to للعادات والحالات التي انتهت، و would للأفعال المتكررة فقط وليس للحالات.',
 ex=['People used to travel by camel across the desert.', 'My grandfather would tell us stories every night.', "I'm used to driving on busy roads now."],
 mistake=('My grandfather would have a farm. ✗', 'My grandfather used to have a farm. ✓', 'have (يملك) حالة، فلا نستخدم would.'),
 rem_ins='Choose the correct answer.',
 rem=[mcq('When I was a child, I ______ play in the street every evening.', ['used to', 'use to', 'am used to', 'get used to'], 'used to'),
      mcq('My grandfather ______ a big farm.', ['would have', 'used to have', 'is used to having', 'would having'], 'used to have'),
      mcq('______ you use to walk to school?', ['Do', 'Did', 'Would', 'Were'], 'Did'),
      mcq("She didn't ______ like vegetables.", ['used to', 'use to', 'using to', 'uses to'], 'use to'),
      mcq('I ______ waking up early. It\'s easy for me.', ['used to', 'am used to', 'would', 'use to'], 'am used to'),
      mcq('It will take time to ______ the new timetable.', ['used to', 'get used to', 'would', 'use to'], 'get used to'),
      mcq('Every summer we ______ go fishing with my uncle.', ['would', 'are used to', 'get used to', 'use to'], 'would'),
      mcq("He isn't used to ______ on the left.", ['drive', 'drove', 'driving', 'driven'], 'driving')],
 enr_ins='Rewrite the sentences using the words in brackets.',
 enr_box='',
 enr=[gap('In the past, I played football every day, but I don\'t now. (used to)', 'I used to play football every day.'),
      gap('Living in a big city is normal for me now. (used to)', "I'm used to living in a big city."),
      gap('My grandmother told us a story every night. (would)', 'My grandmother would tell us a story every night.'),
      gap('Did you have long hair when you were young? (use to)', 'Did you use to have long hair when you were young?'),
      gap('People threw rubbish on the beach, but now they don\'t. (used to)', 'People used to throw rubbish on the beach.'),
      gap('Write three sentences comparing life in Qatar 50 years ago and today using used to, would and be used to.', 'Open answer')]),

