 table=[('check in / check out', 'يسجل الدخول / الخروج', 'at a hotel or airport'), ('set off', 'ينطلق', 'start a journey'), ('see sb off', 'يودّع', ''),
        ('drop sb off', 'يوصل شخصًا', ''), ('pick sb up', 'يقلّ شخصًا', ''), ('put sb up', 'يستضيف في منزله', ''),
        ('get away', 'يأخذ إجازة / يهرب', ''), ('stop over', 'يتوقف أثناء الرحلة', ''), ('call off', 'يلغي', ''), ('take off', 'تقلع', ''),
        ('aisle · boarding pass · hand luggage', 'ممر · بطاقة صعود · أمتعة يد', ''), ('departure lounge · on board · turbulence', 'صالة المغادرة · على متن · مطبات هوائية', '')],
 rule='A phrasal verb is a verb + particle with a new meaning. With an object, many can be separated: drop me off, see him off, put us up.',
