dict(id='g12-m4-future-forms', mod=4, sk=['GR_FUT'], sb='',
 en='Future forms: will, going to, present continuous, present simple', ar='صيغ المستقبل',
 table=[('will + V', 'instant decisions, promises, offers, predictions (I think …)', "I'll carry that for you."),
        ('be going to + V', 'plans made before · predictions with evidence', 'Look at those clouds. It\'s going to rain.'),
        ('Present continuous', 'fixed arrangements with time/place', "I'm meeting Ali at 6."),
        ('Present simple', 'timetables and schedules', 'The flight leaves at 10:30.'),
        ('was / were going to', 'a past plan that did not happen', 'I was going to call you, but I forgot.')],
 rule='Ask: decided now (will)? planned before (going to)? arranged with a time (present continuous)? on a timetable (present simple)?',
 rule_ar='قرار الآن ← will، خطة سابقة ← going to، ترتيب بموعد ← المضارع المستمر، جدول ← المضارع البسيط.',
 ex=['"The phone\'s ringing." "I\'ll answer it."', "We're going to visit Salalah in the summer.", 'The film starts at 8 pm.'],
 mistake=('I go to help you with those bags. ✗', "I'll help you with those bags. ✓", 'العرض والقرار اللحظي بـ will.'),
 rem_ins='Choose the correct answer.',
 rem=[mcq('"I\'m hungry." "I ______ you a sandwich."', ['make', "'ll make", 'am making', 'made'], "'ll make"),
      mcq('Look at that car! It ______ crash!', ['will', 'is going to', 'goes to', 'crashes'], 'is going to'),
      mcq('The train to Al Wakra ______ at 7:40 tomorrow.', ['leaves', 'will leaving', 'is leave', 'left'], 'leaves'),
      mcq("I ______ my dentist at 4 pm. It's in my diary.", ['see', 'am seeing', 'will seeing', 'saw'], 'am seeing'),
      mcq('I ______ visit you, but my car broke down.', ['will', 'am going to', 'was going to', 'would to'], 'was going to'),
      mcq('I promise I ______ tell anyone.', ["won't", "don't", "am not", "wasn't"], "won't"),
      mcq('We have bought the tickets. We ______ fly to Istanbul.', ['will', 'are going to', 'go', 'were'], 'are going to'),
      mcq('I think Qatar ______ the match tomorrow.', ['wins', 'will win', 'is winning', 'won'], 'will win')],
 enr_ins='Correct the mistake in each sentence. Explain your choice in one or two words (decision, plan, arrangement, timetable, evidence).',
 enr_box='',
 enr=[gap('The museum will open at 9 am every day.', 'opens (timetable)'),
      gap('"It\'s cold." "OK, I\'m going to close the window."', "I'll close (instant decision)"),
      gap('I will meet the principal tomorrow at 10. We arranged it last week.', "I'm meeting (arrangement)"),
      gap('Look at the score! Our team will lose.', 'is going to lose (evidence)'),
      gap('I study medicine next year. I decided last summer.', "I'm going to study (plan)"),
      gap('Write four sentences about next weekend, using a different future form in each.', 'Open answer')]),

dict(id='g12-m4-future-continuous-perfect', mod=4, sk=['GR_FUTCP'], sb='',
 en='Future continuous and future perfect', ar='المستقبل المستمر والمستقبل التام',
 table=[('Future continuous', 'will be + V-ing', 'in progress at a future moment'),
        ('', 'This time tomorrow, I will be flying to London.', ''),
        ('Future perfect', 'will have + V3', 'finished before a future time'),
        ('', 'By 2030, they will have built the new line.', ''),
        ('Future perfect continuous', 'will have been + V-ing', 'how long, up to a future time'),
        ('', 'By June, she will have been teaching for 20 years.', ''),
        ('Time words', 'this time next week, at 8 pm tomorrow · by + time, by the time …', '')],
 rule='"This time / at + future time" → will be + V-ing. "By + future time" → will have + V3. After by the time, use present simple: By the time you arrive, we will have eaten.',
 rule_ar='في وقت محدد في المستقبل ← will be + ing. وبحلول وقت مستقبلي ← will have + التصريف الثالث.',
 ex=['At 10 am tomorrow, we will be sitting our English exam.', 'By the end of the week, I will have finished the project.', 'By next September, Paul will have been learning Arabic for two years.'],
 mistake=('By 2030, they will finish the project. ✗', 'By 2030, they will have finished the project. ✓', 'مع by + وقت مستقبلي نستخدم المستقبل التام.'),
 rem_ins='Choose the correct answer.',
 rem=[mcq('This time next week, I ______ on a beach.', ['will lie', 'will be lying', 'will have lain', 'lie'], 'will be lying'),
      mcq('By 8 pm, she ______ her homework.', ['will finish', 'will be finishing', 'will have finished', 'finishes'], 'will have finished'),
      mcq("Don't call at 9. We ______ dinner.", ['will have', 'will be having', 'will have had', 'have'], 'will be having'),
      mcq('By the time you arrive, the film ______.', ['will start', 'will have started', 'starts', 'is starting'], 'will have started'),
      mcq('By next year, he ______ here for ten years.', ['will work', 'will be working', 'will have been working', 'works'], 'will have been working'),
      mcq('At midnight, most people ______.', ['will sleep', 'will be sleeping', 'will have slept', 'sleep'], 'will be sleeping'),
      mcq('______ you ______ the report by Thursday?', ['Will … finish', 'Will … have finished', 'Do … finish', 'Are … finishing'], 'Will … have finished'),
      mcq('Tomorrow at noon, the team ______ to Doha.', ['will be flying', 'will have flown', 'flies', 'is fly'], 'will be flying')],
 enr_ins='Complete the plan for a school trip with the future continuous or future perfect.',
 enr_box='',
 enr=[gap('At 7 am on Sunday, we ______ (travel) to the Al Zubarah Fort.', 'will be travelling'),
      gap('By 10 am, we ______ (arrive) and the guide ______ (meet) us.', 'will have arrived · will have met'),
      gap('At noon, the students ______ (have) lunch in the shade.', 'will be having'),
      gap('By 3 pm, we ______ (visit) the fort and the old town.', 'will have visited'),
      gap('By the end of the trip, we ______ (take) hundreds of photos.', 'will have taken'),
      gap('Write about yourself: "This time next year, I …" and "By 2035, I …".', 'Open answer')]),

dict(id='g12-m4-conditionals', mod=4, sk=['GR_COND'], sb='p.60–61',
 en='Conditionals and alternatives to if', ar='الجمل الشرطية وبدائل if',
 table=[('Zero', 'If / When + present, present', 'facts: If you heat ice, it melts.'),
        ('First', 'If + present, will / can / may / must + V', 'real future: If it rains, we will stay home.'),
        ('Second', 'If + past, would / could + V', 'unreal now: If I had wings, I would fly.'),
        ('unless', '= if … not', "Unless you hurry, you'll miss the bus."),
        ('providing / provided (that) · as long as', '= only if', "You can go providing you're back by 8."),
        ('in case', 'as a precaution', 'Take a coat in case it gets cold.'),
        ('otherwise', '= if not (new sentence)', "Hurry up; otherwise, we'll be late.")],
 rule='Never use will in the if-clause of a first conditional. After unless, use a positive verb (unless you study, NOT unless you don\'t study).',
 rule_ar='لا نستخدم will بعد if في الشرط الأول، وبعد unless يأتي الفعل مثبتًا.',
 ex=['If you exercise regularly, you will feel better.', 'Unless we leave now, we will miss the flight.', 'You can borrow my laptop as long as you take care of it.'],
 mistake=('If it will rain, we will stay inside. ✗', 'If it rains, we will stay inside. ✓', 'بعد if يأتي المضارع وليس will.'),
 rem_ins='Choose the correct answer.',
 rem=[mcq('If you heat water to 100 °C, it ______.', ['boils', 'will boiled', 'boiled', 'would boil'], 'boils'),
      mcq('If it ______ tomorrow, we will cancel the picnic.', ['will rain', 'rains', 'rained', 'raining'], 'rains'),
      mcq('______ you study, you won\'t pass.', ['If', 'Unless', 'Providing', 'In case'], 'Unless'),
      mcq('Take an umbrella ______ it rains.', ['unless', 'in case', 'otherwise', 'providing'], 'in case'),
      mcq('If I ______ rich, I would travel the world.', ['am', 'will be', 'were', 'be'], 'were'),
      mcq('You can go to the party ______ you finish your homework first.', ['unless', 'as long as', 'in case', 'otherwise'], 'as long as'),
      mcq('If you see Ali, ______ him to call me.', ['tell', 'told', 'will told', 'telling'], 'tell'),
      mcq('Leave now; ______, you\'ll be late.', ['unless', 'providing', 'otherwise', 'in case'], 'otherwise')],
 enr_ins='Rewrite each sentence using the word in brackets.',
 enr_box='',
 enr=[gap('If you don\'t book early, you won\'t get a seat. (Unless)', "Unless you book early, you won't get a seat."),
      gap('You can use my car only if you drive carefully. (providing)', 'You can use my car providing (that) you drive carefully.'),
      gap('Take some water because you might get thirsty. (in case)', 'Take some water in case you get thirsty.'),
      gap('Wear a helmet. If you don\'t, you could get hurt. (otherwise)', 'Wear a helmet; otherwise, you could get hurt.'),
      gap('I don\'t have a car, so I can\'t drive you. (If)', 'If I had a car, I would / could drive you.'),
      gap('Write three school rules using unless, as long as and in case.', 'Open answer')]),

